# Writes brand/assets/recipes.json: compose recipes built only from the brand's blocks (python3 scripts/assets/gen-recipes.py).
import json
def at(c,r,w,h): return {"col":c,"row":r,"cols":w,"rows":h}
def B(i,t,a): return {"id":i,"type":t,"at":a}
R={}
def rec(name,group,desc,size,blocks,sample,opts=None,theme='black',grid=None,sizes=None):
    R[name]={"group":group,"description":desc,"size":size,**({"sizes":sizes} if sizes else {}),"theme":theme,**({"grid":grid} if grid else {}),"blocks":blocks,"sample":sample,"options":opts or {}}
# IAB and display ads
for s in ['ad-300x250','ad-336x280']:
    rec(s,'ad',f'Display ad at {s[3:]}: the lockup, a headline and the button.',s,[B('logo','logo',at(0,0,7,2)),B('headline','headline',at(0,3,12,5)),B('button','button',at(0,9,8,3))],{"headline.text":"Every creative in one place.","button.text":"Start free"})
rec('ad-320x50','ad','Mobile banner at 320x50: the logomark, a headline and the button in one row.','ad-320x50',[B('logo','logo',at(0,1,2,10)),B('headline','headline',at(3,0,6,12)),B('button','button',at(9,1,3,10))],{"headline.text":"Every creative.","button.text":"Start"},{"logo.lockup":"mark"})
for s,g in [('ad-728x90',None),('ad-970x250',None)]:
    rec(s,'ad',f'Display ad at {s[3:]}: the lockup, a headline and the button in one row.',s,[B('logo','logo',at(0,3,2,6)),B('headline','headline',at(3,1,6,10)),B('button','button',at(9,3,3,6))],{"headline.text":"Every creative in one place.","button.text":"Start free"})
for s in ['ad-300x600','ad-160x600']:
    rec(s,'ad',f'Display ad at {s[3:]}: the lockup on top, the headline, the light and the button.',s,[B('light','light',at(0,6,12,3)),B('logo','logo',at(0,0,12,1)),B('headline','headline',at(0,2,12,4)),B('button','button',at(0,10,12,2))],{"headline.text":"Every creative in one place.","button.text":"Start free"},{"light.variant":"band"})
rec('meta-feed','ad','Meta feed ad: the light across the top, the headline, a line and the button.','square',[B('light','light',at(0,0,12,4)),B('logo','logo',at(0,5,4,1)),B('headline','headline',at(0,6,12,3)),B('body','body',at(0,9,10,1)),B('button','button',at(0,11,4,1))],{"headline.text":"Every creative in one place.","body.text":"Search the ads every brand runs.","button.text":"Start free"},{"light.variant":"band"},sizes=['square','portrait','story','facebook','linkedin'])
# Product and marketing
rec('quote-card','card','A quote in Funnel Display with the name and role, the light at the foot.','square',[B('light','light',at(0,9,12,3)),B('logo','logo',at(0,0,4,1)),B('quote','quote',at(0,2,12,6))],{"quote.text":"We see every launch the day it ships.","quote.name":"Alex Kim","quote.role":"Head of growth, Acme"},{"light.variant":"band"})
rec('stat-card','card','A figure, what it counts and the lockup.','square',[B('logo','logo',at(0,0,4,1)),B('stat','stat',at(0,3,12,5)),B('light','light',at(0,9,12,3))],{"stat.value":"42%","stat.label":"more launches tracked each week"},{"light.variant":"band"})
rec('launch-card','card','A launch or changelog card: a badge, the headline, a line and the button.','square',[B('light','light',at(0,0,12,3)),B('badge','badge',at(0,4,4,1)),B('headline','headline',at(0,5,12,3)),B('body','body',at(0,8,10,2)),B('button','button',at(0,11,4,1))],{"badge.text":"New","headline.text":"Alerts for every launch.","body.text":"Know the day a brand ships a new ad.","button.text":"See what changed"},{"light.variant":"band"})
rec('feature-card','card','A feature: an icon, a headline and a line on a card.','square',[B('logo','logo',at(0,0,4,1)),B('icon','icon',at(0,3,2,2)),B('headline','headline',at(0,6,12,3)),B('body','body',at(0,9,10,2))],{"headline.text":"Search every network.","body.text":"Meta, TikTok, Instagram and YouTube in one place."},{"icon.name":"search"})
rec('comparison','card','A comparison table under a headline.','landscape',[B('logo','logo',at(0,0,3,1)),B('headline','headline',at(0,2,12,2)),B('table','table',at(0,5,12,6))],{"headline.text":"Plans side by side.","table.rows":"Plan|Searches|Seats\nFree|500|1\nCreator|Unlimited|3"})
rec('pricing-card','card','A plan on a card: the name, the price, what it includes and the button.','square',[B('logo','logo',at(0,0,4,1)),B('card','card',at(2,2,8,9))],{"card.title":"Creator","card.text":"$20 a month.","card.items":"Every network|Unlimited boards","card.cta":"Start free"})
rec('event-card','card','An event or webinar: the date as a label, the title, the speaker slot and the button.','square',[B('light','light',at(0,0,12,3)),B('eyebrow','eyebrow',at(0,4,8,1)),B('headline','headline',at(0,5,12,3)),B('body','body',at(0,8,10,2)),B('button','button',at(0,11,4,1))],{"eyebrow.text":"June 12, 10am PT","headline.text":"Reading a competitor's ads.","body.text":"With Alex Kim, Head of growth, Acme","button.text":"Save a seat"},{"light.variant":"band"})
rec('hiring-card','card','A hiring card: the label, the role and the button.','square',[B('light','light',at(0,10,12,2)),B('logo','logo',at(0,0,4,1)),B('eyebrow','eyebrow',at(0,3,8,1)),B('headline','headline',at(0,4,12,3)),B('button','button',at(0,8,4,1))],{"eyebrow.text":"We are hiring","headline.text":"Founding designer.","button.text":"See the role"},{"light.variant":"band"})
rec('screenshot-card','card','A screenshot in the site\'s browser frame under a headline.','landscape',[B('logo','logo',at(0,0,3,1)),B('headline','headline',at(0,2,5,4)),B('picture','picture',at(6,1,6,10))],{"headline.text":"Every creative in one place."},{"picture.treatment":"frame"})
rec('before-after','card','Two pictures side by side with a label over each.','landscape',[B('before','eyebrow',at(0,0,6,1)),B('after','eyebrow',at(6,0,6,1)),B('picture-1','picture',at(0,1,6,11)),B('picture-2','picture',at(6,1,6,11))],{"before.text":"Before","after.text":"After"},{"picture-1.treatment":"rounded","picture-2.treatment":"rounded"})
rec('chart-card','card','A chart from your numbers under a headline.','square',[B('logo','logo',at(0,0,4,1)),B('headline','headline',at(0,2,12,2)),B('chart','chart',at(0,5,12,6))],{"headline.text":"Launches this week.","chart.data":"Mon 12, Tue 18, Wed 30, Thu 26, Fri 34"})
rec('flow-diagram','card','Three steps as cards in a row (a flow or architecture boxes).','landscape',[B('headline','headline',at(0,0,12,2)),B('step-1','card',at(0,4,4,6)),B('step-2','card',at(4,4,4,6)),B('step-3','card',at(8,4,4,6))],{"headline.text":"From question to answer.","step-1.title":"Ask","step-1.text":"Type a question.","step-2.title":"Search","step-2.text":"Every network at once.","step-3.title":"Act","step-3.text":"Share the board."})
rec('customer-story','card','A customer story: the quote, a figure and the lockup (Acme, never a real customer).','landscape',[B('logo','logo',at(0,0,3,1)),B('quote','quote',at(0,2,7,9)),B('stat','stat',at(8,4,4,4))],{"quote.text":"We found our next campaign in a week.","quote.name":"Alex Kim","quote.role":"Head of growth, Acme","stat.value":"3x","stat.label":"faster research"})
# Documents and print
rec('business-card','print','A business card at print size, bleed and safe margin kept clear.','business-card',[B('logo','logo',at(0,0,6,2)),B('name','headline',at(0,6,12,2)),B('details','body',at(0,9,12,3))],{"name.text":"Alex Kim","details.text":"Head of growth, Acme. alex@acme.com"})
rec('letterhead','print','A letterhead on A4: the lockup on top and the letter under it.','a4',[B('logo','logo',at(0,0,3,1)),B('body','body',at(0,2,10,9)),B('footer','eyebrow',at(0,11,8,1))],{"body.text":"Dear Alex, thank you for meeting with us last week.","footer.text":"Acme Inc. acme.com"})
rec('one-pager','print','A one-pager on A4: headline, a line, a figure, a list and a picture.','a4',[B('logo','logo',at(0,0,3,1)),B('headline','headline',at(0,1,12,2)),B('body','body',at(0,3,10,1)),B('picture','picture',at(0,5,7,5)),B('stat','stat',at(8,5,4,2)),B('list','list',at(8,7,4,3))],{"headline.text":"Every creative in one place.","body.text":"Search the ads every brand runs, across every network.","stat.value":"42%","stat.label":"more launches tracked","list.items":"Every network|Daily updates|Shared boards"},{"picture.treatment":"rounded"})
rec('report-cover','print','A report cover on A4: the light and the title.','a4',[B('light','light',at(0,0,12,6)),B('logo','logo',at(0,11,3,1)),B('headline','headline',at(0,7,12,3)),B('eyebrow','eyebrow',at(0,10,8,1))],{"headline.text":"The state of creative, 2026.","eyebrow.text":"Annual report"},{"light.variant":"field"})
rec('certificate','print','A certificate on A4: the label, the name and a line.','a4',[B('logo','logo',at(4,0,4,1)),B('eyebrow','eyebrow',at(3,3,6,1)),B('name','headline',at(1,4,10,2)),B('body','body',at(2,7,8,2))],{"eyebrow.text":"Certificate of completion","name.text":"Alex Kim","body.text":"Creative research, level one."},{"eyebrow.align":"center","name.align":"center","body.align":"center"})
rec('email-header','email','An email header: the lockup, a headline and the light.','email',[B('light','light',at(6,0,6,12)),B('logo','logo',at(0,0,3,2)),B('headline','headline',at(0,4,6,6))],{"headline.text":"What changed this week."},{"light.variant":"band"})
rec('email-signature','email','An email signature: the lockup, the name and the details.','email-signature',[B('logo','logo',at(0,2,3,8)),B('name','body',at(4,1,8,5)),B('details','body',at(4,6,8,5))],{"name.text":"Alex Kim","details.text":"Head of growth, Acme"})
rec('event-badge','print','An event badge: the lockup, the name and the role.','portrait',[B('light','light',at(0,0,12,3)),B('logo','logo',at(0,4,5,1)),B('name','headline',at(0,6,12,3)),B('role','body',at(0,9,12,2))],{"name.text":"Alex Kim","role.text":"Head of growth, Acme"},{"light.variant":"band"})
# Backgrounds
rec('meeting-background','background','A video-call background: the lockup and the light at the sides, the middle clear for the person.','meeting',[B('light','light',at(0,0,3,12)),B('logo','logo',at(9,0,3,1))],{},{"light.variant":"strip-left"})
rec('desktop-wallpaper','background','A desktop wallpaper: the light and the texture with the lockup small.','desktop',[B('texture','ascii',at(0,0,12,12)),B('light','light',at(0,6,12,6)),B('logo','logo',at(0,0,2,1))],{},{"light.variant":"band"})
rec('phone-wallpaper','background','A phone wallpaper: the light across the lower half, the lockup small.','phone-wallpaper',[B('light','light',at(0,6,12,6)),B('logo','logo',at(4,2,4,1))],{},{"light.variant":"field"})
json.dump({"$comment":"Compose recipes: ready layouts of the brand's blocks for the graphics no template covers (display ads, cards, documents, print, email, backgrounds). `recipe <name>` writes a compose design file from one and draws it; the words are yours (--set block.slot=..., or --sample for the sample copy below, Acme only). Every recipe draws clean at its size with its sample copy (test/recipes.test.ts).","recipes":R},open(__import__('os').path.join(__import__('os').path.dirname(__file__), '..', '..', 'brand', 'assets', 'recipes.json'), 'w'),indent=1)
print(len(R))
